{
  "title": "迷雾森林的异兽",
  "scene": "你站在一片古老森林的入口，阳光几乎无法穿透密集的树冠。前方的路分为三条，左路有一块雕刻着古老图腾的石碑，中路被一丛异常鲜艳的红花遮挡，右路则显得格外寂静，偶尔传来轻微的沙沙声。根据《山海经》的记载，森林深处藏有部落的圣物，但通往圣物的路上往往有异兽守护。你决定先观察一下周围环境。",
  "goal": "找到通往部落圣物的正确路径",
  "clue": "左路的石碑上刻有图腾，暗示着安全的入口；右路传来的沙沙声可能是异兽的移动。",
  "choices": [
    {
      "id": "A",
      "text": "走向左路的石碑",
      "outcome": "石碑上的图腾指引你避开了森林中的陷阱，顺利向森林深处前进。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "穿过中路的红花",
      "outcome": "红花下隐藏着锋利的荆棘，你的行进受到了阻碍，但幸运的是没有受伤。你认为应该找一条更安全的路。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "探索右路的寂静",
      "outcome": "你刚踏入右路，一只隐藏在草丛中的异兽突然出现，幸好你反应迅速，没有被攻击。看来这条路上有危险。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
